package com.cognitivekernel.androidfit;
import android.app.*;import android.content.*;import android.os.Build;import java.util.Calendar;
public class WorkoutReminderReceiver extends BroadcastReceiver {
 static final String CHANNEL="fityar_workout_reminders";
 public static void schedule(Context c,int hour,int minute){AlarmManager am=(AlarmManager)c.getSystemService(Context.ALARM_SERVICE);PendingIntent pi=pending(c);Calendar when=Calendar.getInstance();when.set(Calendar.HOUR_OF_DAY,hour);when.set(Calendar.MINUTE,minute);when.set(Calendar.SECOND,0);if(when.getTimeInMillis()<=System.currentTimeMillis())when.add(Calendar.DAY_OF_YEAR,1);if(am!=null)am.setInexactRepeating(AlarmManager.RTC_WAKEUP,when.getTimeInMillis(),AlarmManager.INTERVAL_DAY,pi);}
 public static void cancel(Context c){AlarmManager am=(AlarmManager)c.getSystemService(Context.ALARM_SERVICE);if(am!=null)am.cancel(pending(c));}
 private static PendingIntent pending(Context c){Intent i=new Intent(c,WorkoutReminderReceiver.class);int flags=PendingIntent.FLAG_UPDATE_CURRENT;if(Build.VERSION.SDK_INT>=23)flags|=PendingIntent.FLAG_IMMUTABLE;return PendingIntent.getBroadcast(c,7412,i,flags);}
 @Override public void onReceive(Context c,Intent i){if(Intent.ACTION_BOOT_COMPLETED.equals(i.getAction())){if(c.getSharedPreferences("fityar_preferences",0).getBoolean("reminder_enabled",false))schedule(c,c.getSharedPreferences("fityar_preferences",0).getInt("reminder_hour",19),c.getSharedPreferences("fityar_preferences",0).getInt("reminder_minute",0));return;}if(!c.getSharedPreferences("fityar_preferences",0).getBoolean("reminder_enabled",false))return;if(Build.VERSION.SDK_INT>=33&&c.checkSelfPermission("android.permission.POST_NOTIFICATIONS")!=android.content.pm.PackageManager.PERMISSION_GRANTED)return;NotificationManager nm=(NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE);if(nm==null)return;if(Build.VERSION.SDK_INT>=26)nm.createNotificationChannel(new NotificationChannel(CHANNEL,"Workout reminders",NotificationManager.IMPORTANCE_DEFAULT));Intent launch=new Intent(c,MainActivity.class);launch.setFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TOP);PendingIntent content=PendingIntent.getActivity(c,7413,launch,PendingIntent.FLAG_UPDATE_CURRENT|(Build.VERSION.SDK_INT>=23?PendingIntent.FLAG_IMMUTABLE:0));Notification.Builder b=Build.VERSION.SDK_INT>=26?new Notification.Builder(c,CHANNEL):new Notification.Builder(c);b.setSmallIcon(android.R.drawable.ic_menu_my_calendar).setContentTitle(c.getString(R.string.reminder_notification_title)).setContentText(c.getString(R.string.reminder_notification_text)).setContentIntent(content).setAutoCancel(true);nm.notify(7414,b.build());}
}